from fastembed.rerank.cross_encoder import TextCrossEncoder
import tomllib


#
import sys
from pathlib import Path

ORC=Path(__file__).resolve().parent
RAG=ORC.parent
SRC=RAG.parent
ROOT=SRC.parent

utils_dir=ROOT/'src'/'rag'/'utils'

sys.path.insert(0,str(utils_dir))
from utils import State
#


with open('config.toml','rb') as f:
    config=tomllib.load(f)


cross_encoder_model_name=config['rerank']['cross_encoder_model']
rerank_topk=config['rerank']['topk']

reranker=TextCrossEncoder(model_name=cross_encoder_model_name)


def reranker(state:State, reranker=reranker, topk=rerank_topk) -> State:

    text_set=[i['text'] for i in state['retr_docs']]
    new_scores=list(reranker.rerank(state['query'], text_set))    

    ranking=[(i, score) for i, score in enumerate(new_scores)]
    ranking.sort(key=lambda x:x[1], reverse=True)

    return {'query':state['query'], 'rerank_docs':[{'text':text_set[i], 'rerank_score':j} for i,j in ranking][:topk-1]}



if __name__=='__main__':

    query='What laws are there against deepfakes'
    retr_set=[{'id': 'f4f14ee9-221a-473b-b174-99991f755450', 'text': "Deepfake detection and regulation\nLegal experts are actively questioning whether current and emerging regulatory frameworks\nadequately balance the advancements in deepfake detection with the protection of individual\nrights. Relevant legislation being scrutinized includes the EU AI Act, the General Data\nProtection Regulation (GDPR), the Digital Services Act in the European Union, as well as the\nfragmented state and federal laws in the United States, the Online Safety Act 2023 in the\nUnited Kingdom, and China's Administrative Provisions on Deep Synthesis in Internet-Based\nInformation Services (commonly known as the Deep Synthesis Provisions). Scholars are\nevaluating if these frameworks effectively address the complex interplay between technology,\nrights, and responsibilities in the context of deepfakes.\nPrevention\nHenry Ajder who works for Deeptrace, a company that detects deepfakes, says there are\nseveral ways to protect against deepfakes in the workplace. Semantic passwords or secret", 'score': 0.5833334, 'source': 'rrf'}, {'id': 'bbe1c1c3-0dae-4ff5-a1a4-b201bee005a5', 'text': 'and subjected to stricter regulation. However, the Act does not explicitly mandate specific\ndeepfake detection mechanisms, nor does it comprehensively address the broader human\nrights implications stemming from the proliferation of such synthetic media. Scholars have\nfurther argued that manufacturer self-assessments are inadequate to address complex\ngenerative harms, necessitating mandatory architectural mandates and standardized\nverification frameworks to ensure effective enforcement.\nPenalties\nNon-compliance with theprohibitions in Article 5 is subject to administrative fines of up to\nEUR 35,000,000 or, if the offender is an undertaking, up to 7% of its total worldwide annual\nturnover, whichever is higher. Other operator obligations may be sanctioned with fines of up\nto EUR 15,000,000 or 3% of worldwide annual turnover, whichever is higher; providing\nincorrect, incomplete or misleading information may be fined up to EUR 7,500,000 or 1% of', 'score': 0.5, 'source': 'rrf'}, {'id': '68ef455a-645a-4de6-971f-db169c202004', 'text': 'Overall, deepfakes are expected to have several implications in media and society, media\nproduction, media representations, media audiences, gender, law, and regulation, and\npolitics.\nAmateur development\nThe term deepfake originated in late 2017 from a Reddit user named "deepfakes". He, along\nwith other members of Reddit\'s "r/deepfakes", shared deepfakes they created; many videos\ninvolved celebrities\' faces swapped onto the bodies of actors in pornographic videos, while\nnon-pornographic content included many videos withactor Nicolas Cage\'s face swapped into\nvarious movies.\nAfter this first introduction, amateur development grew at a quick rate because of the\npresence of open-source software and tutorials on the Internet. The freely available tools like\nFakeApp, FaceSwap, and DeepFaceLab allowed users who did not have any formal education\nin computer science to assemble deepfake videos with consumer hardware. Online forums', 'score': 0.5, 'source': 'rrf'}, {'id': '41dd9eaf-f850-48f2-a1ff-01fc91278984', 'text': 'information via the Internet.\nSee also\nReferences\nFurther reading\nDaniel Immerwahr, "Your Lying Eyes: People now use A.I. togenerate fake videos\nindistinguishable from real ones. How much does it matter?", The New Yorker, 20 November\n2023, pp. 54–59. "If by \'deepfakes\' we mean realistic videos produced using artificial\nintelligence that actually deceive people, then they barely exist. The fakes aren\'t deep, and the\ndeeps aren\'t fake. [...] A.I.-generated videos are not, in general, operating in our media as\ncounterfeited evidence. Their role better resembles that of cartoons, especially smutty ones."\n(p. 59.)\nEmmanouil Billis, "Deepfakes και Ποινικό Δίκαιο [Deepfakes and the Criminal Law]"(in Greek).\nIn: H. Satzger et al. (eds.), The Limits and Future of Criminal Law - Essays in Honor of Christos\nMylonopoulos, Athens, P.N. Sakkoulas, 2024, pp. 689–732.\nExternal links\nSasse, Ben (19 October 2018). "This New Technology Could Send American Politics into a', 'score': 0.3611111, 'source': 'rrf'}, {'id': 'dbb74943-749c-4e20-875c-58508266768b', 'text': "Deepfakes (a portmanteau of 'deep learning' and 'fake') are images, videos, or audio that have\nbeen edited or generated using artificial intelligence, AI-based tools or audio-video editing\nsoftware. They may depict real or fictional people and are considered a form of synthetic\nmedia, that is media that is usually created by artificial intelligence systems by combining\nvarious media elements into a new media artifact.\nWhile the act of creating fake content is not new, deepfakes uniquely leverage machine\nlearning and artificial intelligence techniques, including facial recognition algorithms and\nartificial neural networks such as variational autoencoders and generative adversarial\nnetworks (GANs). In turn, the field of imageforensics has worked to develop techniques to\ndetect manipulated images. Deepfakes have garnered widespread attention for their potential\nuse in creating child sexual abuse material, celebrity pornographic videos, revenge porn, fake", 'score': 0.33333334, 'source': 'rrf'}, {'id': '8900ec15-94eb-4757-a5cc-ce65e53e514c', 'text': "representative for New York's 9th congressional district Yvette Clarke.\nIn 2024, over halfof documented identity fraud involved AI-created forgeries, leading several\nstates to introduce legislation regarding deepfakes, including Virginia, Texas, California, and\nNew York; charges as varied as identity theft, cyberstalking, and revenge porn have been\npursued, while more comprehensive statutes are urged.\nAmong U.S. legislative efforts, on 3 October 2019, California governor Gavin Newsom signed\ninto law Assembly Bills No. 602 and No. 730. Assembly Bill No. 602 provides individuals\ntargeted by sexually explicit deepfake content made without their consent with a cause of\naction against the content's creator. Assembly Bill No. 730 prohibits the distribution of\nmalicious deepfake audio or visual media targeting a candidate running for public office\nwithin 60 days of their election. U.S. representative Yvette Clarke introduced H.R. 5586:", 'score': 0.23333335, 'source': 'rrf'}, {'id': 'fa3e7e1e-702d-4086-a126-39c800e2c51c', 'text': "Johansson.\nSeveral incidents involving sharing of non-consensual deepfake pornography have occurred.\nIn late January 2024, deepfake images of American musician Taylor Swift proliferated. Several\nexperts have warned that deepfake pornography is more quickly created and disseminated,\ndue to the relative ease of using the technology. Canada introduced federal legislation\ntargeting sharing of non-consensual sexually explicit AI-generated photos; most provinces\nalready had such laws. In the United States, the DEFIANCEAct was introduced in March 2024.\nEnvironment\nA large amount of electricity is needed to power generative AI products, making it more\ndifficult for companies to achieve net zero emissions. From 2019 to 2024, Google's\ngreenhouse gas emissions increased by nearly 50%, partly as a result of increased energy\nconsumption by AI data centres.\nBiosecurity and cybersecurity", 'score': 0.2, 'source': 'rrf'}, {'id': '4f7f262e-5983-4c22-a117-6362f7ac31a9', 'text': 'using them.\nDeepfakes\nDeepfakes are digital media generated or altered with AI to impersonate someone. The term\n"deepfake" is a portmanteau of "deep learning" and "fake". It emerged on Reddit in 2017, after\nusers began sharing non-consensually-generated pornographic deepfake videos. By the early', 'score': 0.2, 'source': 'rrf'}, {'id': '2d0d5d6f-6347-45ad-9033-12dd9e803dd7', 'text': 'several ways to protect against deepfakes in the workplace. Semantic passwords or secret\nquestions can be used when holding important conversations. Voice authentication and other', 'score': 0.16666667, 'source': 'rrf'}, {'id': 'cf5b5915-3a30-4491-a313-b98045b4d780', 'text': "bill was revised, the MPA expressed support for the legislation.\nBefore the U.S. Senate Judiciary Subcommittee on Intellectual Property, musician FKA Twigs\ndiscussed her experiences using a digital replica to promote her work, as well as discovering\nAI-generated songs falsely attributed to her online. She emphasized the importance of legal\nprotections that allow artists to control the use of their likeness.\nIn April 2025, a coalition of over 400 artists, including 21 Savage, Missy Elliott, Deadmau5, and\nScarlett Johansson, signed a letter in support of the legislation.\nIn May 2025, country singer Martina McBride appeared before the U.S. Senate Judiciary\nSubcommittee on Privacy, Technology and the Law at a hearing to speak out against\nAI-generated deepfakes. At the CNBC AI Summit in Nashville, she told CNBC's Courtney\nReagan about the impact of deepfakes on the careers and livelihoods of young singers; the\ninvasion and retaliation of the artist-fan bond.\nCriticism", 'score': 0.14285715, 'source': 'rrf'}, {'id': '2cd36be3-c6e3-4166-b5f5-9a66e48c6000', 'text': '$50. On June 27 the creators removed the application and refunded consumers.\nThe US Congress held a senate meeting discussing the widespread impacts of synthetic\nmedia, including deepfakes, describing it as having the "potential to be used to undermine\nnational security, erode\npublic trust in our democracy and other nefarious reasons."\nIn 2019, voice cloning technology was used to successfully impersonate a chief executive\'s\nvoice and demand a fraudulent transfer of €220,000. The case raised concerns about the lack\nof encryption methods over telephones as well as the unconditional trust often given to voice\nand to media in general.\nAudio-visual material is typically recognized in court as accurate evidence of events regardless\nof whether it originates from a suspect\'s phone, social media, or local CCTV footage. However,\nthe increasing prevalence of deepfakes necessitates a close examination of such evidence to\nverify its authenticity and identify potential manipulation.', 'score': 0.14285715, 'source': 'rrf'}, {'id': 'b5a2b690-9dd7-4302-8de6-a8f247c37cad', 'text': "agendas, debating issues, informing decisions, and solving problems throughthe exercise of\npolitical will. People may also start to dismiss real events as fake.\nDefamation\nDeepfakes possess the ability to damage individual entities tremendously. This is because\ndeepfakes are often targeted at one individual, and/or their relations to others in hopes to\ncreate a narrative powerful enough to influence public opinion or beliefs. This can be done\nthrough deepfake voice phishing, which manipulates audio to create fake phone calls or\nconversations. Another method of deepfake use is fabricated private remarks, which\nmanipulate media to convey individuals voicing damaging comments. The quality of a\nnegative video or audio does not need to be that high. As long as someone's likeness and\nactions are recognizable, a deepfake can hurt their reputation.\nIn September 2020, Microsoft made public that they were developing a Deepfake detection\nsoftware tool.", 'score': 0.125, 'source': 'rrf'}, {'id': '76f66f5f-3527-4539-ac94-3901a0ba5135', 'text': 'deepfakes, and humanities and social science approaches that study the social, ethical,\naesthetic implications as well as journalistic and informational implications of deepfakes. As\ndeepfakes have become more sophisticated and more common, with innovations provided by\nAI tools, significant research has gone into developing detection methods and defining the\nfactors driving engagement with deepfakes on the internet. Deepfakes have been shown to\nappear on social media platforms and other parts of the internet for purposes including\nentertainment, education related to deepfakes, and misinformation intended to elicit strong\nreactions. There are gaps in research related to the propagation of deepfakes on social media.\nNegativity and emotional response are the primary driving factors for users sharing\ndeepfakes.\nSocial science and humanities approaches to deepfakes\nIn cinema studies, deepfakes illustrate how "the human face is emerging as a central object of', 'score': 0.125, 'source': 'rrf'}, {'id': 'f032fb9c-b7db-4c57-83b2-02abb2d24c57', 'text': 'tool of disinformation, deepfakes did not necessarily produce stronger reactions or shifts in\nviewpoints than traditional textual disinformation. However, deepfakes did produce a\nreassuring effect on individuals who held preconceived notions that aligned with the\nviewpoint promoted by the deepfake disinformation in the study. Additionally, deepfakes are\neffective when designed to target a specific demographic segment related to a particular\nissue. "Microtargeting" involves understanding nuanced political issues of a specific\ndemographic to create a targeted deepfake. The targeted deepfake is then used to connect\nwith and influence the viewpoint of that demographic. Targeted deepfakeswere found to be\nnotably effective by some researchers. Other researchers in the United Kingdom found that\ndeepfake political disinformation does not have a guaranteed effect on populations beyond\nindicationsthat it may sow distrust or uncertainty in a source that provides the deepfake. The', 'score': 0.11111111, 'source': 'rrf'}, {'id': '762432ba-cabc-4552-a6a5-6c94546142a2', 'text': "employees, unless the tools have been independently audited for bias.\nThe Responsible AI Safety and Education Act (RAISE Act) is a New York State law that imposes\ntransparency, safety, and reporting requirements on developers of large frontier artificial\nintelligence models. The law was signed by Governor Kathy Hochul on December 19, 2025. It\nis expected to take effect on January 1, 2027.\nTennessee\nOn March 21, 2024, the State of Tennessee enacted legislation called the ELVIS Act, aimed\nspecifically at audio deepfakes, and voice cloning. This legislation was the first enacted\nlegislation in the nation aimed at regulating AI simulation of image, voiceand likeness.  The\nbill passed unanimously in the Tennessee House of Representatives and Senate. This\nlegislation's success was hoped by its supporters to inspire similar actions in other states,\ncontributingto a unified approach to copyright and privacy in the digital age, and to reinforce", 'score': 0.1, 'source': 'rrf'}, {'id': '100b0b7c-a6ba-4312-9616-489b45c6dc17', 'text': 'need to detect short and often subtlespoofed segments within predominantly genuine audio\nfurther increases the difficulty of the problem.\nVideo\nMost of the academic research surrounding deepfakes focuses on the detection of deepfake\nvideos. Oneapproach to deepfake detection is to use algorithms to recognize patterns and\npick up subtle inconsistencies that arise in deepfake videos. For example, researchers have\ndeveloped automatic systems that examine videos for errors such as irregular blinking\npatterns of lighting. This approach has been criticized because deepfake detection is\ncharacterized by a "moving goal post" where the production of deepfakes continues to change\nand improve as algorithms to detect deepfakes improve. In order to assess the most effective\nalgorithms for detecting deepfakes, a coalition of leading technology companies hosted the\nDeepfake Detection Challenge to accelerate the technology for identifying manipulated', 'score': 0.1, 'source': 'rrf'}, {'id': '24a782f8-405c-4164-bda8-17b1dcf829d2', 'text': 'Chat site Discord took action against deepfakepornography in 2018, and has taken a general\nstance against deepfakes. Gfycat began removing all deepfakes from its site on 31 January\n2018.\nReddit banned the r/deepfakes subreddit on 7 February 2018, due to the policy violation of\n"involuntary pornography". Also in February 2018, Pornhub said that it would ban deepfake\nvideos on its website because it is considered "non consensual content" which violates their\nterms of service. They had also stated previously that they will take down content flagged as\ndeepfakes. Writers from Motherboard reported that searching "deepfakes" on Pornhub still\nreturned multiple recent deepfake videos.\nGoogle added "involuntary synthetic pornographic imagery" to its ban list in September 2018,\nallowing anyone to request the block of results showing their fake nudes. In May 2022, Google', 'score':0.09090909, 'source': 'rrf'}, {'id': '60c955dd-4190-4008-869c-d550ce73dfd6', 'text': 'The NO FAKES Act or the Nurture Originals, Foster Art, and Keep Entertainment Safe Act, is\nproposed United States federal legislation concerning digital replicas. The bill was first\nintroduced in 2023 as a discussion draft, formally introduced in 2024, and reintroduced in\n2025. If enacted, the bill would establish a federal right ofpublicity, giving public figures and\nprivate individuals greater control over the creation and use of digital replicas of their\nlikenesses, including artificial intelligence (AI)-generated content.\nIf passed,the NO FAKES Act would create a legal framework for licensing digital replicas,\nincluding provisions for liability, safe harbors, and statutory exceptions. The proposal has\nreceived broad support from the entertainment and technology industries. However, digital\nrights organizations have raised concerns that the Act risks chilling protected speech.\nBackground\nEntertainment industry concerns', 'score': 0.09090909, 'source': 'rrf'}, {'id': '4df90ff4-55ff-46ab-b251-16063451f71b', 'text': 'strengthened state law, upheld public safety, protected minors, and called it a "common-sense\nbill" protecting and promoting the "common good", children, and fell within the "proper role"\nof government. The Texas Public Policy Foundation also expressed their support for the law. A\npolicy director for aforementioned conservative think tank, Zach Whiting, told the Texas\nSenate Committee on Criminal Justice, on March 4, 2025, that the foundation would assist\nlegislators ans staff to "advance any and all measures to protect kids online" and shared an\nexcerpt from a research paper about threats posed by A.I. in creating "sexually explicit\ndeepfakes of children".\nOpposition\nAlthough the bill passed both chambers unanimously, there were some reports that the bill\nstalled due to opposition from Democratic lawmakers. Additionally, some individuals\nexpressed concerns about the broad nature of the law\'s provisions. Anime Matsuri co-founder', 'score': 0.083333336, 'source': 'rrf'}, {'id': '898b5cbb-0793-4fc4-af07-4bb289305332', 'text': 'the fake videos are non-consensual pornography. Most of the victims of these videos were\ncelebrities or high-profile individuals.\nIn February 2018, r/deepfakes was banned by Reddit for sharing involuntary pornography.\nOther websites have also banned the use of deepfakes for involuntary pornography, including\nthe social media platform Twitter and the pornography site Pornhub. However, some websites\nhave not yet banned Deepfake content, including 4chan and 8chan.\nNon-pornographic deepfake content continues to grow in popularity with videos from\nYouTube creators such as Ctrl Shift Face and Shamook. A mobile application, Impressions, was\nlaunched for iOS in March 2020. The app provides a platform for users to deepfake celebrity\nfaces into videos in a matter of minutes.\nImage synthesis\nImage synthesis is the artificial production of visual media, especially through algorithmic\nmeans. In the emerging world of synthetic media, the work of digital-image creation—once', 'score': 0.083333336, 'source': 'rrf'}, {'id': '8fac7e4a-176a-447d-9c96-903f380c88ca', 'text': 'The NO FAKES Act provides remedies that are similar to those available under U.S. copyright\nlaw. Under the Act, individuals may be held liable for either statutory damages of $5,000 or\nactual damages for creating or distributing an unauthorized digital replica. \nThe legislation also establishes a tiered liability framework for online service providers. Those\nthat make good faith efforts to comply with the Act may face statutory damages of up to\n$25,000 per work for violations or actual damages. Providers that do not undertake such\ncompliance efforts may be liable for $5,000 per unauthorized display or transmission of a\ndigital replica, with damages capped at $750,000 per work. \nExclusions\nThe Act includes several exceptions to liability that are modeled in part on fair use principles.\nDigital replicas are excluded from liability when "used in a bona fide news, public affairs, or\nsports broadcast or account;" in a documentary or historical context; or in a way that is', 'score': 0.07692308, 'source': 'rrf'}, {'id': '18ac6dcd-06e2-459e-bd24-d14523d5e16f', 'text': "Politics\nResearchers have studied the capabilities and effects of deepfakes when used in\ndisinformation campaigns, including the potential for deepfakes to circumvent a person's\nscepticism and influence their views on an issue. Unlike crude misinformation, political\npropaganda via generative AI often co-opts cultural tropes, visual media, and satire to craft\nemotionally resonant messages that are difficult to fact-check without losing nuance. Due to\nthe continued advancement in technology that improves deceptive capabilities of deepfakes,\nsome scholars believe that deepfakes could pose a significant threat to democratic societies.\nStudies have investigated the effects of political deepfakes. In two separate studies focusing\non Dutch participants, it was found that deepfakes have varying effects on an audience. As a\ntool of disinformation, deepfakes did not necessarily produce stronger reactions or shifts in", 'score': 0.07692308, 'source': 'rrf'}, {'id': 'f84ede06-7122-47ac-953e-b2d4bc01e1b0', 'text': 'TRAIGA, or the Texas Responsible Artificial Intelligence Governance Act, is a state law\nregulating the development and deployment of artificial intelligence (AI) systems in Texas.\nSponsored by Representative Giovanni Capriglione, the Act establishes a framework\ngoverning certain uses of AI, outlines prohibited uses, and creates obligations on state\ngovernment entities, among other provisions. TRAIGA was signed into law in 2025 and took\neffect on January 1, 2026. \nThe law applies to AI developers and deployers that conduct business in Texas or whose\nsystems are used by Texas residents. It prohibits the intentional development or deployment\nof AI systems to incite harm, violate constitutional rights, engage in unlawful discrimination,\nand produce child sexual abuse material or unlawful deepfakes. TRAIGA also establishes the\nTexas Artificial Intelligence Council and creates a regulatory sandbox program. The Texas\nAttorney General is charged with enforcement.', 'score': 0.071428575, 'source': 'rrf'}, {'id': '166f0d48-5b51-4376-ba48-22b8e3354a83', 'text': 'Fraud and scams\nFraudsters and scammers make use of deepfakes to trick people into fake investment\nschemes, financial fraud, cryptocurrencies, sending money, and following endorsements. The\nlikenesses of celebrities and politicians have been used for large-scale scams, as well as those\nof private individuals, which are used in spearphishing attacks. According to the Better\nBusiness Bureau, deepfake scams are becoming more prevalent. These scams are responsible\nfor an estimated $12 billion in fraud losses globally. According to a recent report these\nnumbers are expected to reach $40 Billion over the next three years. By 2030, the global\nfinancial impact of deepfake fraud is projected to reach $58.3 billion, driven by the emergence\nof "Fraud-as-a-Service". The average loss per criminal deepfake incident now exceeds\n$500,000, and composite "Frankenstein" synthetic identities are expected to cost the UK\neconomy £4.2 billion by 2027.', 'score': 0.071428575, 'source': 'rrf'}, {'id': '329fb7fc-7aa5-4fdb-a5fc-d0e18c0ec86c', 'text': 'history by retrofitting canonical cinema with new star performers". Film scholar Christopher\nHolliday analyses how altering the gender and race of performers in familiar movie scenes\ndestabilizes gender classifications and categories. The concept of "queering" deepfakes is also\ndiscussed in Oliver M. Gingrich\'s discussion of media artworks that use deepfakes to reframe\ngender, including British artist Jake Elwes\' Zizi: Queering the Dataset, an artwork that uses\ndeepfakes of drag queens to intentionally play with gender. The aesthetic potentials of\ndeepfakes are also beginning to be explored. Theatre historian John Fletcher notes that early\ndemonstrations of deepfakes are presented as performances, and situates these in the\ncontext of theatre, discussing "some of the more troubling paradigm shifts" that deepfakes\nrepresent as a performance genre.\nWhile most English-language academic studies of deepfakes focus on the Western anxieties', 'score': 0.06666667, 'source': 'rrf'}, {'id': '3b5c0ccd-4a42-4ebe-aaa6-f9a77ab7cf34', 'text': 'which was partly based on explicit deepfakes.\nIn July 2025, Donald Trump posted a deepfake on his Truth Social account, depicting former\npresident Barack Obama getting arrested at the White House and put in prison.\nPornography\nIn 2017, Deepfake pornography prominently surfaced on the Internet, particularly on Reddit.\nAs of2019, many deepfakes on the internet feature pornography of female celebrities whose\nlikeness is typically used without their consent. A report published in October 2019 by Dutch\ncybersecurity startup Deeptrace estimated that 96% of all deepfakes online were\npornographic.\nAs of 2018, a Daisy Ridley deepfake first captured attention, among others. As of October\n2019, most of the deepfake subjects on the internet were British and American actors.\nHowever, around a quarter of the subjects are South Korean, the majority of which are K-pop\nstars.\nIn June 2019, a downloadable Windows and Linux application called DeepNude was released', 'score': 0.0625, 'source': 'rrf'}, {'id': '5b86ba87-d0f0-4255-aa50-a96daa6b8419', 'text': 'The Act further states that licensing requirements do not apply to licenses established\nthrough collective bargaining agreements that contain provisions governing the use of digital\nreplicas.\nThe Act does not impose secondary liability on providers of generative artificial intelligence\ntools or services whose primarypurpose is not the creation of unauthorized digital replicas.\nPreemption\nThe NO FAKES Act preempts laws that protect "an individual\'s voice and visual likeness rights\nin connection with a digital replica, asdefined in this Act, in an expressive work." However, the\nAct preserves state laws governing digital replicas enacted before January 2, 2025, as well as\nstate laws addressing digital replicas that portray sexually explicit conduct.\nHistory\nIn 2023, Senators Marsha Blackburn, Chris Coons, Amy Klobuchar, and Thom Tillis introduced\nthe NO FAKES Act as a discussion draft to lay out the general contours of the proposed bill and', 'score': 0.0625, 'source': 'rrf'}]

